<?php
require_once __DIR__.'/verificar_sesion.php';$db=conexion();$desde=$_GET['desde']??date('Y-m-01');$hasta=$_GET['hasta']??date('Y-m-d');$error='';$filas=false;if($desde>$hasta)$error='La fecha inicial no puede ser posterior a la fecha final.';if($error===''){$stmt=$db->prepare('SELECT p.id,p.fecha,p.total,p.estado,CONCAT(c.nombre," ",c.apellidos) cliente FROM pedidos p INNER JOIN clientes c ON c.id=p.cliente_id WHERE DATE(p.fecha) BETWEEN ? AND ? ORDER BY p.fecha DESC');$stmt->bind_param('ss',$desde,$hasta);$stmt->execute();$filas=$stmt->get_result();}$titulo='Informe de ventas';require __DIR__.'/includes/encabezado.php';?>
<main class="contenido"><h1>Informe de ventas</h1><p>Consulta las ventas realizadas entre dos fechas.</p><?php if($error):?><p class="error"><?php echo e($error);?></p><?php endif;?><form class="filtros-fecha"><label>Desde <input type="date" name="desde" value="<?php echo e($desde);?>" required></label><label>Hasta <input type="date" name="hasta" value="<?php echo e($hasta);?>" required></label><button class="boton">Consultar</button><a class="boton" href="exportar.php?desde=<?php echo urlencode($desde);?>&hasta=<?php echo urlencode($hasta);?>">Descargar CSV</a></form><?php if($filas):?><div class="tabla-scroll"><table><thead><tr><th>Pedido</th><th>Fecha</th><th>Cliente</th><th>Estado</th><th>Total</th></tr></thead><tbody><?php $suma=0;while($v=$filas->fetch_assoc()):$suma+=(float)$v['total'];?><tr><td><?php echo (int)$v['id'];?></td><td><?php echo e($v['fecha']);?></td><td><?php echo e($v['cliente']);?></td><td><?php echo e($v['estado']);?></td><td><?php echo e(precio_texto($v['total']));?></td></tr><?php endwhile;?></tbody><tfoot><tr><th colspan="4">Total</th><th><?php echo e(precio_texto($suma));?></th></tr></tfoot></table></div><?php endif;?></main>
<?php if(isset($stmt))$stmt->close();$db->close();require __DIR__.'/includes/pie.php';?>